VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.39,"Lecture four. Selection and operators. This is about who gets to breed, and how children are made."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":23.336,"caps":[[0.5,8.99,"Generational: the whole population is replaced."],[9.24,16.69,"Elitism copies the best across unchanged."],[16.94,22.55,"Steady-state: one child replaces the weakest."]],"warp":[[0,0],[0.5,0.9],[9.24,5.2],[16.94,8.8],[23.336,13]]},{"dur":21.687,"caps":[[0.5,7.39,"A child with fitness 0.5 arrives."],[7.64,14.93,"First weaker stops early. Weakest checks all five."],[15.18,20.79,"The 0.1 survives: more variety is kept."]],"warp":[[0,0],[0.5,0.8],[7.64,2.6],[15.18,6.2],[21.687,10]]},{"dur":25.055,"caps":[[0.55,8.72,"Each row is a generation. Orange = copies of the best."],[8.97,14.1,"Only selection acts: no mutation, no crossover."],[14.35,23.4,"Too weak: no progress. Too strong: one copy wins."]],"warp":[[0,0],[0.55,1],[8.97,3.6],[14.35,7.2],[25.055,12]]},{"dur":28.305,"caps":[[0.5,6.35,"Each slice is sized by fitness."],[6.6,14.93,"The bigger the slice, the likelier the pick."],[15.18,22.47,"One superfit individual takes 99% of the wheel."],[22.72,27.45,"It is picked again and again."]],"warp":[[0,0],[0.5,0.8],[6.6,3.4],[15.18,6.8],[22.72,9.6],[28.305,12]]},{"dur":21.618,"caps":[[0.5,4.43,"Roulette: the superfit takes 99%."],[4.68,11.57,"Rank: only the order counts, not the gaps."],[11.82,20.47,"The exponent b turns the pressure up or down."]],"warp":[[0,0],[0.5,0.8],[4.68,3.4],[11.82,7.2],[21.618,11]]},{"dur":21.664,"caps":[[0.5,6.67,"Draw two at random. The better one wins."],[6.92,11.65,"The best was not even drawn."],[11.9,16.39,"A bigger t means tougher competition."],[16.64,20.73,"The best wins more often as t grows."]],"warp":[[0,0],[0.5,0.9],[6.92,3.8],[11.9,5.2],[16.64,7.8],[21.664,11]]},{"dur":23.359,"caps":[[0.5,9.07,"Each encoding needs its own kind of mutation."],[9.32,16.21,"Re-rolling a tour breaks it: D twice, J lost."],[16.46,22.15,"Swapping two genes keeps every city once."]],"warp":[[0,0],[0.5,0.8],[9.32,5],[16.46,8.4],[23.359,12]]},{"dur":20.039,"caps":[[0.77,7.9,"One cut: swap the tails."],[8.15,12.56,"Two cuts: swap the middle part."],[12.81,18.98,"Uniform: a 1 in the mask swaps that gene."]],"warp":[[0,0],[0.77,1.4],[8.15,5.8],[12.81,8.6],[20.039,12]]},{"dur":28.282,"caps":[[0.5,9.15,"Fitness: pixels that match, blank ones too."],[9.4,17.49,"Two recipes race. Both rely on mutation."],[17.74,26.79,"Algorithm 1 got there first, in this run."]],"warp":[[0,0],[0.5,0.8],[9.4,3.6],[17.74,6.6],[28.282,11]]},{"dur":17.09,"caps":[],"warp":[[0,0],[0.5,0.9],[6.84,1.9],[11.74,2.9],[17.09,9]]}]};
